std::vector<double>load(const char*name,size_t n){std::ifstream f(name,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=(std::streamoff)(8*n))exit(3);f.seekg(0);std::vector<double>a(n);f.read((char*)a.data(),8*n);if(!f)exit(3);return a;}
template<class T>struct Buffer{T*base,*data;size_t n;std::vector<T>initial,host;Buffer(size_t N,const std::vector<double>&pre,size_t&pos):n(N),initial(n+16,G),host(n+16){for(size_t i=0;i<n;++i)initial[8+i]=pre[pos++];CK(cudaMalloc(&base,(n+16)*sizeof(T)));data=base+8;copyin();}void copyin(){CK(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}void read(){CK(cudaMemcpy(host.data(),base,host.size()*sizeof(T),cudaMemcpyDeviceToHost));}};
struct Case{int b,m,k,n,nnz,repeat;Buffer<float>A,B;Buffer<int>off,col;Buffer<float>C;cusparseHandle_t h;cusparseDnMatDescr_t a,bb;cusparseSpMatDescr_t c;float alpha=1,beta=0;void*buf;size_t bytes=0;decltype(&cusparseSDDMM)compute;
Case(int batch,int M,int K,int N,int nz,int reps,const std::vector<double>&pre,size_t&pos,decltype(compute)fn):b(batch),m(M),k(K),n(N),nnz(nz),repeat(reps),A(b*m*k,pre,pos),B(b*k*n,pre,pos),off(b*(m+1),pre,pos),col(b*nnz,pre,pos),C(b*nnz,pre,pos),compute(fn){
CS(cusparseCreate(&h));int version;CS(cusparseGetVersion(h,&version));cusparsePointerMode_t pm;CS(cusparseGetPointerMode(h,&pm));cudaStream_t stream;CS(cusparseGetStream(h,&stream));if(version!=12001||pm!=CUSPARSE_POINTER_MODE_HOST||stream!=0)exit(3);printf("STUDY_VENDOR cuSPARSE=%d pointermode=%d stream=0 batches=%d\n",version,int(pm),b);
CS(cusparseCreateDnMat(&a,m,k,k,A.data,CUDA_R_32F,CUSPARSE_ORDER_ROW));CS(cusparseDnMatSetStridedBatch(a,b,m*k));CS(cusparseCreateDnMat(&bb,k,n,n,B.data,CUDA_R_32F,CUSPARSE_ORDER_ROW));CS(cusparseDnMatSetStridedBatch(bb,b,k*n));CS(cusparseCreateCsr(&c,m,n,nnz,off.data,col.data,C.data,CUSPARSE_INDEX_32I,CUSPARSE_INDEX_32I,CUSPARSE_INDEX_BASE_ZERO,CUDA_R_32F));CS(cusparseCsrSetStridedBatch(c,b,m+1,nnz));
