std::vector<double>execute(double&seconds,bool&ok){C.copyin();C.read();std::vector<float>before=C.host;ok&=before==C.initial;CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;++rep)CS(compute(h,CUSPARSE_OPERATION_NON_TRANSPOSE,CUSPARSE_OPERATION_NON_TRANSPOSE,&alpha,a,bb,&beta,c,CUDA_R_32F,CUSPARSE_SDDMM_ALG_DEFAULT,buf));CK(cudaDeviceSynchronize());seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();A.read();B.read();off.read();col.read();C.read();std::vector<double>out;for(size_t i=0;i<C.n;++i)out.push_back(C.host[8+i]);auto input=[&](auto&x){ok&=x.host==x.initial;for(size_t i=0;i<x.n;++i)out.push_back(x.host[8+i]);};input(A);input(B);input(off);input(col);for(size_t i=0;i<C.n;++i)out.push_back(before[8+i]);auto guard=[&](auto&x){for(size_t i=0;i<x.host.size();++i)if(i<8||i>=x.n+8){out.push_back(x.host[i]);ok&=x.host[i]==G;}};guard(A);guard(B);guard(off);guard(col);guard(C);return out;}
